-- Japan pilot: curators + the 5 places they link to (Task 23 follow-up, 2026-10-19).
-- Source: docs/research/japan_pilot/results_2026-10-19/curators*.csv, places*.csv.
-- Upserts only. affiliations are mapped to the DB's source ids (existing SRC rows keep their id).
BEGIN;
INSERT INTO public.sources (source_id, name, source_type, market, discipline_focus, tier, website_url, instagram_url, scrape_method, status, needs_verification, notes, name_ja, about, neighborhood, address, calendar_url, scene_tags, underground_score, newcomer_friendly, foreigner_notes, evidence_url, verified_at, is_demo) VALUES
  ('tyo-theatercommons', 'Theater Commons Tokyo', 'festival', 'tokyo', ARRAY['theatre','performance']::TEXT[], 2, 'https://theatercommons.tokyo/en/', NULL, 'html_calendar', 'active', false, 'Independent festival run by Arts Commons Tokyo with partner cultural institutes; experimental, lecture-format and site-based performance outside theatres', 'シアターコモンズ', '10th edition ran 22 Feb-8 Mar 2026 (Translating Commons). Not in the client''s window; put it in the calendar for early 2027. Added for the curators link (Chiaki Soma).', 'Citywide', NULL, 'https://theatercommons.tokyo/en/', ARRAY['experimental','festival','lecture_performance','site_specific']::TEXT[], 4, 'unknown', 'English site', 'https://theatercommons.tokyo/en/about/', '2026-10-19', false),
  ('tyo-cinn', 'C.I.N.N. (Contact Improvisation Nippon Network)', 'collective', 'tokyo', ARRAY['dance']::TEXT[], 2, 'https://www.contactimprov-nn.com/', NULL, NULL, 'active', false, 'Non-profit group of Kanto dancers that runs the Tokyo Contact Improvisation Festival and lists community CI workshops and jams', NULL, 'Founded as SPIRAL in 2003. The 2026 festival was held in Katsuura, Chiba. Possibly related to tyo-nishiogi-ci, which cites the same website, but I did not confirm the link; the main session should check before merging.', NULL, NULL, 'https://contactimprov-nn.com/class-info/', ARRAY[]::TEXT[], 3, NULL, NULL, 'https://www.contactimprov-nn.com/', '2026-10-19', false),
  ('tyo-bal', 'Body Arts Laboratory (Whenever Wherever Festival)', 'collective', 'tokyo', ARRAY['dance','performance']::TEXT[], 2, 'https://bodyartslabo.com/', NULL, NULL, 'active', false, 'Artist-run dance and performance organisation; its festival uses public and community spaces rather than theatres', NULL, 'Founded 2008; became a general incorporated association in 2021 (per Arts Council Tokyo).', NULL, NULL, NULL, ARRAY[]::TEXT[], 4, NULL, NULL, 'https://www.artscouncil-tokyo.jp/en/grants/program/27829/', '2026-10-19', false),
  ('tyo-the5thfloor', 'The 5th Floor', 'venue', 'tokyo', ARRAY['visual_art']::TEXT[], 2, 'https://the5thfloor.org/', NULL, NULL, 'active', false, 'Independent non-commercial curatorial space in a former dormitory building; programmes guest curators and runs a curator residency', NULL, 'Opened Feb 2020 (Forbes Japan 2024). Director Tomoya Iwata. 2025 show listed on TAB: https://www.tokyoartbeat.com/events/-/Phenomena-and-Records-One-Record-Three-Rooms/5-C2-E814-D/2025-08-29 (building: 花園アレイ 5F, Taito-ku). The address comes from that TAB listing and wasn''t cross-checked on the official site.', 'Ikenohata (Nezu)', 'Hanazono Alley 5F, 3-3-9 Ikenohata, Taito-ku, Tokyo', NULL, ARRAY['curatorial space','alternative space','curator residency']::TEXT[], 4, NULL, NULL, 'https://the5thfloor.org/', '2026-10-19', false),
  ('tyo-multiplespirits', 'Multiple Spirits', 'collective', 'tokyo', ARRAY['visual_art','performance']::TEXT[], 2, NULL, NULL, NULL, 'active', false, 'Queer feminist zine and research platform that curates exhibitions; AWT Focus 2026 curator', 'マルスピ', 'Founded 2018 by Mai Endo and Mika Maruyama. No fixed space. Own website not verified.', NULL, NULL, NULL, ARRAY[]::TEXT[], 3, NULL, NULL, 'https://www.artweektokyo.com/en/institution-gallery/waitingroom/', '2026-10-19', false)
ON CONFLICT (source_id) DO UPDATE SET name = EXCLUDED.name, source_type = EXCLUDED.source_type, market = EXCLUDED.market, discipline_focus = EXCLUDED.discipline_focus, tier = EXCLUDED.tier, website_url = EXCLUDED.website_url, instagram_url = EXCLUDED.instagram_url, scrape_method = EXCLUDED.scrape_method, status = EXCLUDED.status, needs_verification = EXCLUDED.needs_verification, notes = EXCLUDED.notes, name_ja = EXCLUDED.name_ja, about = EXCLUDED.about, neighborhood = EXCLUDED.neighborhood, address = EXCLUDED.address, calendar_url = EXCLUDED.calendar_url, scene_tags = EXCLUDED.scene_tags, underground_score = EXCLUDED.underground_score, newcomer_friendly = EXCLUDED.newcomer_friendly, foreigner_notes = EXCLUDED.foreigner_notes, evidence_url = EXCLUDED.evidence_url, verified_at = EXCLUDED.verified_at, is_demo = EXCLUDED.is_demo;
INSERT INTO public.curators (curator_id, name, name_ja, role_label, market, about, disciplines, affiliations, website_url, instagram_url, evidence_url, verified_at, status) VALUES
  ('kyo-cur-kawasaki-yoko', 'Yoko Kawasaki', '川崎陽子', 'Artistic director', 'kyoto', 'Yoko Kawasaki is co-artistic director of Kyoto Experiment, the Kyoto International Performing Arts Festival, a post she has shared with Yuya Tsukahara since the 2025 edition. The two directors shape the programme and write the festival''s yearly directors'' text.

The 2026 edition, the 17th, ran 3 to 25 October under the phrase ''Carrying a pebble in my pocket'', with a Shows programme built around memories and stories passed on through the body, alongside the festival''s other two programme strands.

For a visiting artist, Kyoto Experiment is the main yearly meeting point of the Kansai and international performing-arts world. Post-show talks are the natural place to say hello; the festival office is reachable through its official contact page.', ARRAY['dance','theatre','performance']::TEXT[], ARRAY['SRC072']::TEXT[], NULL, NULL, 'https://kyoto-ex.jp/en/news/2026-opening/', '2026-10-19', 'active'),
  ('kyo-cur-tsukahara-yuya', 'Yuya Tsukahara', '塚原悠也', 'Artistic director', 'kyoto', 'Yuya Tsukahara is co-artistic director of Kyoto Experiment, sharing the post with Yoko Kawasaki since the 2025 edition. Together they choose the works and set the festival''s annual theme.

In 2026 the festival''s 17th edition (3 to 25 October) took the idea of small pebbles carried in a pocket as its guide: works about memory, letters, migration and poetry conveyed through performance, presented across Kyoto''s theatres and other sites.

For a visiting artist, the festival''s closing week and its post-show events are the best chance to meet the people who programme contemporary performance in Kyoto. Contact goes through the festival''s official contact page, not personal channels.', ARRAY['performance','dance','theatre']::TEXT[], ARRAY['SRC072']::TEXT[], NULL, NULL, 'https://kyoto-ex.jp/en/news/2026-opening/', '2026-10-19', 'active'),
  ('kyo-cur-katsura-kan', 'Kan Katsura', '桂勘', 'Festival director', 'kyoto', 'Kan Katsura is a butoh dancer who organises the Kyoto International Butoh Festival. The festival credits him as organiser together with its executive committee. The 4th edition runs 7 to 15 November 2026, with evening performances by Japanese and international butoh artists, a daily workshop series, and paid live streaming.

He also performs in the festival (13 November) and teaches one of its workshops (8 November). A pre-festival evening under his name takes place at UrBANGUILD on 26 October 2026.

For a visiting artist, the workshops and the UrBANGUILD pre-event are the most direct way in. The festival lists a public contact address on its site.', ARRAY['dance','performance','music']::TEXT[], ARRAY['kyo-butohfes','kyo-urbanguild','kyo-spacelfan']::TEXT[], NULL, NULL, 'https://kyoto-butohfes.com/kbf-2026/', '2026-10-19', 'active'),
  ('kyo-cur-okuyama-riko', 'Riko Okuyama', '奥山理子', 'Organiser', 'kyoto', 'Riko Okuyama is representative director of HAPS (Higashiyama Artists Placement Service), the Kyoto organisation that helps young artists live, make work and show in the city. HAPS calls itself a general consultation point for artists and for the people who support art.

Beyond help with studios and housing, HAPS has run its ''Art and Inclusive Society'' programme since 2017 and, since 2022, a commission from the Agency for Cultural Affairs to support arts activity by people with disabilities. It runs the HAPS office, HAPS HOUSE in Higashi-Kujo and the HAPS studio.

For a visiting artist, HAPS is the best first contact in Kyoto for practical questions and introductions to local people. Use the organisation''s contact page.', ARRAY['visual_art','performance']::TEXT[], ARRAY['kyo-haps']::TEXT[], NULL, NULL, 'https://haps-kyoto.com/about/', '2026-10-19', 'active'),
  ('kyo-cur-fujita-mizuho', 'Mizuho Fujita', '藤田瑞穂', 'Curator', 'kyoto', 'Mizuho Fujita is chief curator and programme director of @KCUA, the gallery of Kyoto City University of Arts. The gallery opened in 2010 as an off-campus space and moved onto the university''s new campus east of Kyoto Station in October 2023.

@KCUA shows special exhibitions planned by its curatorial staff, open-call shows by faculty, students and alumni, and workshops and lectures with visiting artists. The gallery describes Fujita''s work as cross-disciplinary exhibitions and projects made with specialists from other fields, recently around biodiversity and more-than-human perspectives.

For a visiting artist, openings and talks at @KCUA are where Kyoto''s art-school scene gathers.', ARRAY['visual_art']::TEXT[], ARRAY['kyo-kcua']::TEXT[], NULL, NULL, 'https://gallery.kcua.ac.jp/about/', '2026-10-19', 'active'),
  ('kyo-cur-ogura-emi', 'Emi Ogura', '小倉笑', 'Programmer', 'kyoto', 'Emi Ogura is a Kyoto-based dancer, choreographer and director, and co-programme director of the Kyoto International Dance Workshop Festival (''Kyoto no Atsui Natsu''), which Kyoto Art Center co-organises. She has worked in Kyoto since 2014 and founded the creative group SMILE in 2021.

At the festival''s 2026 early-summer edition (2 to 6 May) she led ''Dance in English'', a session that prepares participants for classes given by visiting teachers in English. She also performs on Kyoto''s small stages, including FOuR DANCERS at UrBANGUILD on 27 October 2026.

For a visiting artist, the festival (main edition each August) is the easiest structured way into Kyoto''s dance community.', ARRAY['dance','performance']::TEXT[], ARRAY['kyo-kidwf','kyo-kac','kyo-urbanguild']::TEXT[], NULL, NULL, 'https://www.kac.or.jp/events/20260330/', '2026-10-19', 'active'),
  ('kyo-cur-tani-ryuichi', 'Ryuichi Tani', '谷竜一', 'Programmer', 'kyoto', 'Ryuichi Tani is a programme director at Kyoto Art Center (KAC), the city-run arts centre in a former primary school in central Kyoto. On the centre''s site he speaks for its studio programme: former classrooms lent as creation studios after a selection process, meant for young artists and new projects.

KAC also runs open calls, an artist-in-residence programme and free workshops, and co-organises Kyoto Experiment and the Kyoto International Dance Workshop Festival. His programming work centres on theatre and dance.

For a visiting artist who needs rehearsal or studio space in Kyoto, the KAC studio programme is the door, and the centre invites informal questions before an application.', ARRAY['theatre','dance']::TEXT[], ARRAY['kyo-kac']::TEXT[], NULL, NULL, 'https://www.kac.or.jp/about/', '2026-10-19', 'active'),
  ('kyo-cur-iida-jinichiro', 'Jinichiro Iida', '飯田仁一郎', 'Organiser', 'kyoto', 'Jinichiro Iida co-leads Boro Festa, Kyoto''s self-produced autumn music festival, now in its 25th year. In a 2026 interview, co-organiser Mogura names Iida, of the band Limited Express (has gone?), and himself as the current core of organisation and production.

Boro Festa is booked and built in-house from booking to set-up, with student volunteers and the audience pitching in. The 2026 edition runs 31 October to 3 November at KBS Hall and Club Metro, with two all-night sessions.

For a visiting artist, the Club Metro night sessions are where the festival''s more experimental side shows up.', ARRAY['music']::TEXT[], ARRAY['kyo-borofesta','kyo-clubmetro']::TEXT[], NULL, NULL, 'https://l-tike.com/borofesta/', '2026-10-19', 'active'),
  ('kyo-cur-mogura', 'Mogura', '土龍', 'Organiser', 'kyoto', 'Mogura is one of Boro Festa''s founding staff and, with Jinichiro Iida, the current core of its organisation and production. Day to day he manages Live House nano in Kyoto.

He describes a clear pipeline: young bands play nano, then the August pre-event Nano Boro, then Boro Festa itself. The 2026 festival, its 25th, runs 31 October to 3 November at KBS Hall and Club Metro, with staff and volunteers sharing the organising work.

For a visiting artist, Live House nano and the Nano Boro pre-event are the grassroots end of Kyoto''s independent music circuit, and the place to ask about the scene.', ARRAY['music']::TEXT[], ARRAY['kyo-borofesta']::TEXT[], NULL, NULL, 'https://l-tike.com/borofesta/', '2026-10-19', 'active'),
  ('tyo-cur-okada-toshiki', 'Toshiki Okada', '岡田利規', 'Artistic director', 'tokyo', 'Toshiki Okada, a playwright, novelist and director, is artistic director of the performing-arts festival Autumn Meteorite 2026 Tokyo. From fiscal 2026 he is also artistic director of the performing-arts division of Tokyo Metropolitan Theatre.

The 2026 edition (9 October to 3 November, centred on the theatre in Ikebukuro) is the second under his direction and part of Tokyo Festival 2026. It has 13 Japanese and international productions plus lectures, workshops and networking programmes. Its stated aims are new creation, international reach and training the next generation.

For a visiting artist, the festival''s exchange programmes and post-show events are the realistic point of contact.', ARRAY['theatre','performance','dance']::TEXT[], ARRAY['tyo-autumnmeteorite','tyo-geigeki']::TEXT[], NULL, NULL, 'https://autumnmeteorite.jp/ja', '2026-10-19', 'active'),
  ('tyo-cur-kishimoto-kako', 'Kako Kishimoto', '岸本佳子', 'Artistic director', 'tokyo', 'Kako Kishimoto is artistic director of BUoY, the arts centre in Kita-Senju set in a building whose upper floor was once a bowling alley and whose basement was a public bath, renovated by BUoY''s own members.

In BUoY''s statement she frames it as a place for young, sharp, intentional art that questions what is taken for granted. The programme mixes dance, performance, music and exhibitions in the basement and the upstairs galleries and café. In October 2026 it hosted the RAW PARTY performance night and the dance piece IGNIS.

For a visiting artist, BUoY''s open-format nights are the way to show work here. RAW PARTY includes an open independent slot.', ARRAY['performance','dance','theatre','visual_art','music']::TEXT[], ARRAY['tyo-buoy','tyo-rawparty']::TEXT[], NULL, NULL, 'https://buoy.or.jp/about/', '2026-10-19', 'active'),
  ('tyo-cur-itoh-naoko', 'Naoko Itoh', '伊藤直子', 'Artistic director', 'tokyo', 'Naoko Itoh founded Kagurazaka Session House in 1991 as a small theatre for dance. She runs it as company representative and supervises the planning of its dance programme. She also leads her company Mademoiselle Cinema, formed in 1993.

Session House runs open dance classes and more than 40 performance and workshop projects a year, with platforms for young choreographers, international exchange, and calls for solo shows (Dzone 2027 applications opened in 2026). Mademoiselle Cinema presents ''Okuni Monogatari'' there on 19 and 20 December 2026.

For a visiting artist, drop-in classes and the short-piece platforms are the most direct way into Tokyo''s contemporary dance community.', ARRAY['dance']::TEXT[], ARRAY['SRC075']::TEXT[], NULL, NULL, 'https://session-house.net/about_sessionhouse.html', '2026-10-19', 'active'),
  ('tyo-cur-ogawa-nozomu', 'Nozomu Ogawa', '小川希', 'Director', 'tokyo', 'Nozomu Ogawa founded and directs Art Center Ongoing in Kichijoji (2008). In June 2025 he also opened Art Center NEW, underground at Shin-Takashima Station in Yokohama. Ongoing combines exhibition space, a bar and a residency, and mostly shows emerging artists.

In Tokyo Art Beat''s review of 2025 he described himself as working outside the art mainstream. He championed small non-commercial spaces, including Alternative Art Week, run by the Reigai network of independent art spaces.

For a visiting artist, Ongoing''s openings and its bar are a standard meeting point for Tokyo''s independent art scene.', ARRAY['visual_art','performance','music']::TEXT[], ARRAY['SRC260']::TEXT[], NULL, NULL, 'https://www.tokyoartbeat.com/articles/-/best-exhibitions-of-2025-nozomu-ogawa-202512', '2026-10-19', 'active'),
  ('tyo-cur-soma-chiaki', 'Chiaki Soma', '相馬千秋', 'Festival director', 'tokyo', 'Chiaki Soma is director of Theater Commons Tokyo and chairs its executive committee as representative director of Arts Commons Tokyo. The festival applies theatrical ideas to everyday life and the city, and presents performances and learning programmes at sites around Tokyo with partner cultural institutes such as the Goethe-Institut Tokyo and the Institut français du Japon.

Its 10th edition, ''Translating Commons'', ran 22 February to 8 March 2026.

For a visiting artist, Theater Commons is a key node for experimental, lecture-format and site-based performance in Tokyo, and a festival to put in the calendar for early 2027.', ARRAY['theatre','performance']::TEXT[], ARRAY['tyo-theatercommons']::TEXT[], NULL, NULL, 'https://theatercommons.tokyo/en/about/', '2026-10-19', 'active'),
  ('tyo-cur-takahashi-hiroko', 'Hiroko Takahashi', '髙橋弘子', 'Organiser', 'tokyo', 'Hiroko Takahashi is the representative of C.I.N.N. (Contact Improvisation Nippon Network), a non-profit group of Kanto-area dancers that promotes contact improvisation. She has led the group since it was founded as SPIRAL in 2003 and handles the planning, production and running of its activities.

C.I.N.N. organises the Tokyo Contact Improvisation Festival. The 2026 edition ran 2-5 May 2026 at the Nippon Budokan Training Center in Katsuura, Chiba. Its website also lists one-off CI workshops, jams and roundtables in Tokyo.

For a visiting artist, she is the main contact for Tokyo''s contact improvisation community and its yearly festival, which invites teachers from abroad.', ARRAY['dance']::TEXT[], ARRAY['tyo-cinn']::TEXT[], NULL, NULL, 'https://contactimprov-nn.com/staff/', '2026-10-19', 'active'),
  ('tyo-cur-yamazaki-kota', 'Kota Yamazaki', '山崎広太', 'Festival director', 'tokyo', 'Kota Yamazaki is the director of Body Arts Laboratory (BAL), an artist-run organisation for dance and performance founded in Tokyo in 2008. Through BAL he runs the Whenever Wherever Festival (WWFes), an experimental dance and performance festival programmed by a collective of dancers and choreographers.

WWFes has run regularly since 2009, with editions in 2025 and 2026. According to Arts Council Tokyo, the 12th festival took place in February 2026 at public, community and municipal spaces in Minato Ward. BAL''s site also lists a team of five curators, including Aokid.

For a visiting artist, WWFes is one of Tokyo''s few artist-run festivals of experimental dance, set in non-theatre spaces.', ARRAY['dance','performance']::TEXT[], ARRAY['tyo-bal']::TEXT[], NULL, NULL, 'https://bodyartslabo.com/about', '2026-10-19', 'active'),
  ('tyo-cur-iwata-tomoya', 'Tomoya Iwata', '岩田智哉', 'Artistic director', 'tokyo', 'Tomoya Iwata is a curator and has directed The 5th Floor since April 2022. The 5th Floor is a curatorial space on the fifth floor of a former dormitory building in Ikenohata, a few minutes from Nezu station in Taito-ku. Since opening in 2020 it has centred on curation itself, with around 40 exhibitions by some 50 curators in its first four years and a curator-in-residence programme.

In autumn 2026 Iwata curated ''Portal: AfroAsia'' (16 Oct - 29 Nov 2026) with AfroAsia Collective (Che Onejoon and Sun A Moon). In 2025 the space hosted ''Phenomena and Records: One Record, Three Rooms'' (Aug - Oct 2025).

For a visiting artist or curator, he is a good contact for small, research-led exhibition projects and curatorial exchange in Tokyo. This is a non-commercial context, not a sales gallery.', ARRAY['visual_art']::TEXT[], ARRAY['tyo-the5thfloor']::TEXT[], NULL, NULL, 'https://the5thfloor.org/', '2026-10-19', 'active'),
  ('tyo-cur-endo-mai', 'Mai Endo', '遠藤麻衣', 'Curator', 'tokyo', 'Mai Endo is a Tokyo-based artist and actor. In 2018 she co-founded Multiple Spirits with the curator Mika Maruyama. It is a bilingual Japanese-English zine and research platform on queer feminist art practice, and through it Endo also curates and organises.

Art Week Tokyo 2026 (4-8 Nov) invited Multiple Spirits as one of the ten AWT Focus curators. The collective presents ''Patchwork of Ruffled Wings'' at Waitingroom, with printed matter, textiles and works by Japanese and international artists. Earlier work includes ''Anytime Lunatic - Family Abolition'' at gallery αM (2024), Roppongi Crossing 2025 and Invocation #4: Tokyo (2025). Art Basel''s 2026 Tokyo city film features her guiding viewers through the city''s artist-run spaces.

For a visiting artist working on queer or feminist themes, she is a key contact in Tokyo''s independent scene.', ARRAY['visual_art','photography','film','performance']::TEXT[], ARRAY['tyo-multiplespirits']::TEXT[], NULL, NULL, 'https://www.artweektokyo.com/en/institution-gallery/waitingroom/', '2026-10-19', 'active')
ON CONFLICT (curator_id) DO UPDATE SET name = EXCLUDED.name, name_ja = EXCLUDED.name_ja, role_label = EXCLUDED.role_label, market = EXCLUDED.market, about = EXCLUDED.about, disciplines = EXCLUDED.disciplines, affiliations = EXCLUDED.affiliations, website_url = EXCLUDED.website_url, instagram_url = EXCLUDED.instagram_url, evidence_url = EXCLUDED.evidence_url, verified_at = EXCLUDED.verified_at, status = EXCLUDED.status;
COMMIT;
